values
  ('BA', 'BA-P-17', 'PDV 17 % — nabavke od registrovanih obveznika PDV-a u BiH (kupovina)', '{"en":"VAT 17% — purchases from registered VAT payers in Bosnia and Herzegovina"}'::jsonb, null, 'percent', 17, 'purchase', 'domestic', date '2006-01-01', null, 'Zakon o porezu na dodanu vrijednost, član 23 (standardna stopa 17 %) u vezi s članom 32 — poreski obveznik ima pravo odbiti PDV koji je obavezan platiti ili ga je platio na nabavku dobara ili usluga od drugog poreskog obveznika, ako ta dobra ili usluge koristi za promet dobara i usluga koji podliježe PDV-u.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BA', 'BA-P-IMPORT', 'PDV 17 % — uvoz dobara u Bosnu i Hercegovinu (kupovina)', '{"en":"VAT 17% — import of goods into Bosnia and Herzegovina"}'::jsonb, null, 'percent', 17, 'purchase', 'import', date '2006-01-01', null, 'Zakon o porezu na dodanu vrijednost, član 23 (standardna stopa 17 %) u vezi s članom 21 (poreska osnovica pri uvozu dobara) — PDV na uvoz obračunava i naplaćuje Uprava za indirektno oporezivanje po carinskim propisima, a obveznik ga odbija kao ulazni porez u skladu s članom 32, stav 8, tačka 2 Zakona.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BA', 'BA-S-17', 'PDV 17 % — promet dobara i usluga na teritoriji BiH (prodaja)', '{"en":"VAT 17% — sale of goods and services in Bosnia and Herzegovina"}'::jsonb, null, 'percent', 17, 'sale', 'domestic', date '2006-01-01', null, 'Zakon o porezu na dodanu vrijednost ("Službeni glasnik BiH", br. 9/05, 35/05, 100/08, 33/17 i 46/23), član 23 — standardna stopa PDV-a na oporezivi promet dobara i usluga i uvoz dobara u Bosnu i Hercegovinu iznosi 17 %. Ovo je jedina pozitivna stopa koju Zakon poznaje: nema snižene stope.', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BA', 'BA-S-EXEMPT-EDU', 'Oslobođeno od PDV-a — usluge obrazovanja (prodaja)', '{"en":"Exempt from VAT — education services"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2006-01-01', null, 'Zakon o porezu na dodanu vrijednost, član 24, stav 1, tačka 4 — od PDV-a su oslobođene usluge obrazovanja (predškolsko, osnovno, srednje obrazovanje, obrazovanje u okviru daljnjeg obrazovanja i univerziteta), kao i promet dobara i usluga usko povezanih s tim djelatnostima, ako se te djelatnosti obavljaju u skladu s propisima koji uređuju tu oblast.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null),
  ('BA', 'BA-S-EXPORT', 'PDV 0 % — izvoz dobara iz Bosne i Hercegovine (prodaja)', '{"en":"VAT 0% — export of goods from Bosnia and Herzegovina"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2006-01-01', null, 'Zakon o porezu na dodanu vrijednost, član 27, stav 1, tačka 1 — oslobođen je (oporezuje se po nultoj stopi) izvoz dobara iz Bosne i Hercegovine od strane ili u ime prodavca.', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-law', null, null, null, null)
