insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('BA-FBIH-BS', 'BA', 'default', 'Bilans stanja — Izvještaj o finansijskom položaju', 'balance_sheet', 'MRS/MSFI za MSP (FBiH)', date '2022-01-01', null, 'Pravilnik o sadržaju i formi obrazaca finansijskih izvještaja za privredna društva ("Službene novine Federacije BiH", broj 82/10), Prilog 1 — Bilans stanja, čije su pozicije (A-E, rimski i arapski podnaslovi) preuzete od reda do reda; naslijedio ga je od 01.01.2022. istoimeni obrazac uz Pravilnik o kontnom okviru i sadržaju konta za privredna društva ("Službene novine Federacije BiH", broj 81/21), čiji puni tekst ovaj paket nije mogao strojno pročitati. Ovaj paket transkribuje strukturu i nazive pozicija onako kako ih nosi Prilog 1 Pravilnika 82/10 (grupe konta po pozicijama), a ne doslovne AOP oznake obrasca 81/21, koje bi trebalo provjeriti prije podnošenja stvarnog izvještaja — vidjeti README.md.', 'fs-2010'),
  ('BA-FBIH-IS', 'BA', 'default', 'Bilans uspjeha — Izvještaj o ukupnom rezultatu za period', 'income_statement', 'MRS/MSFI za MSP (FBiH)', date '2022-01-01', null, 'Pravilnik o sadržaju i formi obrazaca finansijskih izvještaja za privredna društva ("Službene novine Federacije BiH", broj 82/10), Prilog 2 — Bilans uspjeha, čije su pozicije preuzete od reda do reda; naslijedio ga je od 01.01.2022. istoimeni obrazac uz Pravilnik o kontnom okviru i sadržaju konta za privredna društva ("Službene novine Federacije BiH", broj 81/21), čiji puni tekst ovaj paket nije mogao strojno pročitati. Ovaj paket ne razlikuje, kao službeni obrazac, poseban red za dobit i poseban red za gubitak istog međuzbira: svaki takav red ovdje je jedan red sa predznakom (pozitivna vrijednost — dobit, negativna — gubitak). Porez na dobit nije uključen — vidjeti README.md.', 'fs-2010')
on conflict (code) do update set
