update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{NNNNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Zakon o porezu na dodanu vrijednost, član 55 — poreski obveznik je obavezan izdati fakturu ili drugi dokument koji služi kao faktura za svaki promet dobara i usluga, osim za promet oslobođen po čl. 24 i 25. Zakon ne propisuje jedinstven oblik broja fakture; format ovog paketa je primjer sekvencijalnog numerisanja, a ne jedina zakonom nametnuta forma.',
  numbering_source_key          = 'vat-law',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Zakon o porezu na dodanu vrijednost, član 17, stav 1 — poreska obaveza nastaje u trenutku koji nastupi najranije od sljedećih događaja: isporuke dobara ili izvršenja usluga, izdavanja fakture u skladu sa Zakonom, plaćanja ili djelimičnog plaćanja prije izdavanja fakture, odnosno nastanka obaveze plaćanja carinskog duga pri uvozu. Ovo je pravilo ''najranijeg od tri događaja'', gdje je izdavanje fakture samostalan okidač jednako kao isporuka i plaćanje — nijedna od tih triju činjenica nema prednost po pravilu formata (za razliku od Belgije ili Luksemburga, gdje je datum isporuke princip a datum fakture izuzetak). `earliest_of_delivery_or_payment` ovdje je približna vrijednost: obuhvata isporuku i plaćanje, ali ne i samostalno izdavanje fakture prije jednog od njih dvoje kao treći okidač. Propust je zabilježen u README.md i u docs/international.md, odjeljak ''From Bosnia and Herzegovina''.',
  tax_point_source_key          = 'vat-law',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Zakon o porezu na dodanu vrijednost, član 55, stav 6 — knjižno odobrenje (credit note) izdaje se kada je roba vraćena nakon izdavanja fakture, kada dobavljač naknadno odobri sniženje cijene ili popust, ili kada dobavljač naknadno primi dodatno plaćanje za isporučena dobra ili usluge; ispravka se, dakle, vrši novim dokumentom, a ne izmjenom već izdate fakture.',
  posted_edit_policy_source_key = 'vat-law',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Zakon o porezu na dodanu vrijednost, član 55 — faktura se izdaje kupcu, a njen sadržaj i uvjeti izdavanja bliže se uređuju podzakonskim aktom UIO-a (Pravilnik o primjeni Zakona o porezu na dodatu vrijednost); nijedan od pročitanih izvora ne propisuje opću obavezu strukturirane elektronske fakture (e-Faktura) niti državnu platformu za razmjenu ili validaciju faktura između poslovnih subjekata — postoji isključivo elektronsko podnošenje same prijave PDV-a (obavezno od januara 2019.) preko portala e-Porezi. `profile` ostaje prazan jer nijedan profil izgrađen na semantičkom modelu EN 16931 (Peppol BIS, Factur-X, XRechnung, PINT) nije zakonski propisan niti poznat iz istraženih izvora. Propust je zabilježen u README.md i u docs/international.md, odjeljak ''From Bosnia and Herzegovina''.',
  einvoice_source_key           = 'vat-law',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'BA';
